import{_ as t,C as r,o,c as i,a2 as n,E as s}from"./chunks/framework.Bbwa0s72.js";const u=JSON.parse('{"title":"Specification","description":"","frontmatter":{},"headers":[],"relativePath":"spec/index.md","filePath":"spec/index.md"}'),c={name:"spec/index.md"};function d(l,e,m,h,p,f){const a=r("StatusNote");return o(),i("div",null,[e[0]||(e[0]=n('<h1 id="specification" tabindex="-1">Specification <a class="header-anchor" href="#specification" aria-label="Permalink to &quot;Specification&quot;">​</a></h1><h2 id="identity" tabindex="-1">Identity <a class="header-anchor" href="#identity" aria-label="Permalink to &quot;Identity&quot;">​</a></h2><p>An exact <strong>FormRef</strong> is the join of an API group, a kind, a definition version, and a schema digest. Compatibility is never inferred from a kind name alone: the same kind in a different epoch is a different contract. Form groups are namespaced into <a href="/spec/form-families.html">Form Families</a>; the Host API group is a protocol compatibility identity independent of any nested Form group.</p><table tabindex="0"><thead><tr><th>Surface</th><th>Identity</th></tr></thead><tbody><tr><td>Current Form Family</td><td><code>edge.forms.takoform.com/v1beta1</code> (15 Experimental <code>0.1.0</code> Forms)</td></tr><tr><td>Current Host API wire</td><td><code>forms.takoform.com/v1beta1</code>, discovered at <code>/.well-known/takoform/v1beta1</code></td></tr><tr><td>Current package envelope</td><td><code>packages.forms.takoform.com/v1alpha4</code></td></tr><tr><td>Retained provider-v2 FormRef</td><td><code>forms.takoform.com/v1alpha2</code>, wire discovered at <code>/.well-known/takoform/v1alpha2</code></td></tr><tr><td>Retained provider-v2 package envelope</td><td><code>packages.forms.takoform.com/v1alpha3</code></td></tr><tr><td>Legacy FormRef</td><td><code>forms.takoform.com/v1alpha1</code> (frozen)</td></tr><tr><td>Provider</td><td><code>v2.0.0</code> current published · <code>v1.0.3</code> Legacy · stable <code>v2.1.0</code> release target (<code>candidate-only</code> until owner publication)</td></tr></tbody></table><p>The <code>forms.takoform.com/v1alpha2</code> epoch and its nine <code>0.1.0</code> candidates are retained provider-v2 preview source; they are not the basis for new specification work. The provider&#39;s SemVer is independent of every API identity.</p><h2 id="current-lane-contracts" tabindex="-1">Current-lane contracts <a class="header-anchor" href="#current-lane-contracts" aria-label="Permalink to &quot;Current-lane contracts&quot;">​</a></h2><ul><li><a href="/spec/form-families.html">Form Families</a> — namespaced Form groups and the Edge Platform Family</li><li><a href="/spec/host-api/v1beta1.html">Host API v1beta1</a> — uid/generation/revision identity, long-running operations, fencing</li><li><a href="/spec/interface-contract/">Interface contracts</a> — exact capability contracts a Form&#39;s service exposes</li><li><a href="/spec/binding-contract/">Binding contracts</a> — typed outward capability use held by revisions</li><li><a href="/spec/artifact-transport/">Artifact transport</a> — content-addressed artifact upload and manifests</li></ul><h2 id="normative-schemas" tabindex="-1">Normative schemas <a class="header-anchor" href="#normative-schemas" aria-label="Permalink to &quot;Normative schemas&quot;">​</a></h2><p>Published at <code>forms.takoform.com/schemas/...</code>. Current Beta identities:</p><ul><li><a href="/schemas/v1beta1/form-ref.schema.json">form-ref v1beta1</a></li><li><a href="/schemas/v1beta1/form-definition.schema.json">form-definition v1beta1</a></li><li><a href="/schemas/v1beta1/host-api-wire.schema.json">host-api-wire v1beta1</a></li><li><a href="/schemas/v1alpha4/package-index.schema.json">package-index v1alpha4</a></li></ul><p>Retained provider-v2 lane:</p><ul><li><a href="/schemas/v1alpha2/form-ref.schema.json">form-ref v1alpha2</a></li><li><a href="/schemas/v1alpha2/form-definition.schema.json">form-definition v1alpha2</a></li><li><a href="/schemas/v1alpha3/package-index.schema.json">package-index v1alpha3</a></li><li><a href="/schemas/v1alpha2/host-api-wire.schema.json">host-api-wire v1alpha2</a></li></ul><p>The v1alpha3 schema identities remain immutable retained history and are never rewritten as Beta.</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><p>A Form moves Proposal → Experimental → Stable → Legacy. Maturity is earned from independent implementation and evidence, never from publication or popularity. Every new Form starts from prior art (OCCI, CIMI, TOSCA, Kubernetes/Crossplane, provider-native resources).</p><h2 id="more-surfaces" tabindex="-1">More surfaces <a class="header-anchor" href="#more-surfaces" aria-label="Permalink to &quot;More surfaces&quot;">​</a></h2><ul><li><a href="/proposals/">Proposals</a> — mutable design material for Forms that have not earned a public FormRef</li><li><a href="/forms/">Form inventory</a> — generated candidate and family inventory</li><li><a href="/conformance/">Conformance</a> — executable compatibility evidence</li><li><a href="/release/">Release</a> — provider and Form Package publication boundary</li><li><a href="/docs/glossary.html">Glossary</a> — terms used across the documentation</li></ul>',17)),s(a)])}const b=t(c,[["render",d]]);export{u as __pageData,b as default};
